(async()=>{if(new URLSearchParams(location.search).get('profile')!=='storage-check')return;while(!window.EmberQA)await new Promise(r=>setTimeout(r,100));const q=EmberQA,D=SurvivalData,W=EmberTerrain;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='storage-report';report.hidden=true;report.style='position:fixed;bottom:0;left:0;background:white;z-index:100';document.body.append(report);const result={},check=(k,v)=>{result[k]=!!v;report.textContent=JSON.stringify(result,null,2);if(!v)throw Error(k);};
q.apply({...D.fresh(),inventory:{hammer:1,pickaxe:1,wood:10,fiber:4},hand:'hammer'});let p;outer:for(let z=10;z<70;z+=2)for(let x=-20;x<20;x+=2){const v={x,z,y:W.ground(x,z)};if(!q.storagePlacement(v)){p=v;break outer;}}check('placementFound',p);Object.assign(q.state,{x:p.x,z:p.z+3,y:W.ground(p.x,p.z+3),yaw:0});q.deposit('storagebox');const pile=q.state.piles.find(v=>v.items.wood===10);check('materialsPlaced',pile);q.craft(pile.id,'storagebox');const job=q.state.jobs.find(v=>v.type==='storagebox');check('craftStarted',job);q.state.hand='pickaxe';q.work(job,1);check('pickaxeCannotCraft',job.progress===0);q.state.hand='hammer';q.work(job,15);let box=q.state.structures.find(s=>s.type==='storagebox');check('hammerCompletesBox',box?.progress===1&&!q.state.jobs.length);check('solidBox',q.world.blocked(box.x,box.z,box.y,q.state));check('supportsStandingOnLid',Math.abs(q.world.floor(box.x,box.z,box.y+1.5,q.state)-box.y-1.14)<.001);check('canWalkOffLid',!q.world.blocked(box.x,box.z,box.y+1.14,q.state));q.storageMenu(box);
D.add(q.state.inventory,'wood',150);D.add(q.state.inventory,'stone',12);q.storageMenu(box);const click=(a,shift=false)=>document.querySelector('[data-action="'+a+'"]').dispatchEvent(new MouseEvent('click',{bubbles:true,shiftKey:shift}));click('storeput:'+box.id+':wood');check('singleDeposit',box.items.wood===1);click('storeput:'+box.id+':wood',true);check('stackDeposit',box.items.wood===100&&D.storageSlots(box.items).length===2);click('storetake:'+box.id+':wood');check('singleWithdrawal',box.items.wood===99&&q.state.inventory.wood===51);check('twentySlots',document.querySelectorAll('.storageColumns section:first-child .storageSlot').length===20);check('fullBoxRecoveryDisabled',document.querySelector('[data-action="storerecover:'+box.id+'"]').disabled);document.getElementById('storageName').value='鉱石と木材';click('storename:'+box.id);check('named',box.storageName==='鉱石と木材');q.state.checkpoint={id:'test-fire',x:p.x,z:p.z,y:p.y};check('save',q.saveSlot(0));box.items={};check('load',q.loadSlot(0));q.setPlaying(false);box=q.state.structures.find(s=>s.type==='storagebox');check('savedContentsRestored',box.items.wood===99&&box.storageName==='鉱石と木材');q.storageMenu(box);click('storeall:'+box.id);check('takeAll',!Object.keys(box.items).length&&q.state.inventory.wood===150);click('storerecover:'+box.id);check('recoverEmpty',!q.state.structures.some(s=>s.id===box.id)&&q.state.inventory.storagebox===1);q.useItem('storagebox');check('placeAgain',q.state.structures.some(s=>s.type==='storagebox')&&!q.state.inventory.storagebox);check('validSave',D.validSave(q.snapshot()));
box=q.state.structures.find(s=>s.type==='storagebox');D.storageTransfer(q.state,box,'wood',true,120);D.storageTransfer(q.state,box,'stone',true,12);box.storageName='木材・石の保管箱';q.storageMenu(box);const show=document.createElement('button');show.textContent='設置した箱を見る';show.onclick=()=>{report.hidden=true;q.close(false);q.setPlaying(true);Object.assign(q.state,{worldTime:360,automaticTime:false,pitch:-.28});q.move(0);};document.getElementById('modalBody').append(show);result.done=true;report.textContent=JSON.stringify(result,null,2);document.title='収納箱の検証完了';})().catch(e=>{document.title='Storage QA error';document.getElementById('storage-report').hidden=false;document.getElementById('storage-report').textContent+='\n'+e.stack;});
